import sys; sys.path.append('/tmp')
import numpy as np
from engine import *

for pat in ['P1', 'P2', 'P3', 'P4', 'P5']:
    deck_zones = {f'Z{k}': pat for k in range(1, 13)}
    collector_lines = {k: 'C2' for k in ['CH-S','CH-N','CH-W','CH-E','DR-S1','DR-S2','DR-N1','DR-N2','DR-W1','DR-W2','DR-E1','DR-E2','OP-1S','OP-1N','OP-1W','OP-1E','OP-2S','OP-2N','OP-2W','OP-2E']}
    for kj in [0.0, 210.0, 420.0, 630.0, 960.0]:
        wall_kj = {'S': kj, 'N': kj, 'W': kj, 'E': kj}
        K_sr, _, _, ws_sr = build_stage_b(deck_zones, collector_lines, wall_kj, rigid=False, erection=False)
        # Check max displacement in X and Y under base and future (and 100/30)
        F_X1 = build_load_vector('X', +1, 'future')
        F_Y1 = build_load_vector('Y', +1, 'future')
        d_X = np.linalg.solve(K_sr, F_X1)
        d_Y = np.linalg.solve(K_sr, F_Y1)
        ux_max = np.max(np.abs(d_X[0::2]))
        uy_max = np.max(np.abs(d_Y[1::2]))
        # Amplified deflection Cd * delta / Ie where Cd = 4.0, Ie = 1.25 -> factor = 3.2
        print(f'Deck {pat}, kj={kj:5.0f}: ux_max={ux_max:.4f} in (Cd/Ie*ux={3.2*ux_max:.3f} in), uy_max={uy_max:.4f} in (Cd/Ie*uy={3.2*uy_max:.3f} in)')
"

